from collections import deque


class Solution:
    def eventualSafeNodes(self, graph: list[list[int]]) -> list[int]:
        n = len(graph)
        rev = [[] for _ in range(n)]
        out_deg = [0] * n
        for u in range(n):                       # build reverse graph: O(V + E)
            out_deg[u] = len(graph[u])
            for v in graph[u]:
                rev[v].append(u)
        queue = deque(u for u in range(n) if out_deg[u] == 0)   # terminal nodes are safe
        safe = [False] * n
        while queue:                             # each node and reverse edge handled once
            v = queue.popleft()
            safe[v] = True
            for u in rev[v]:
                out_deg[u] -= 1                  # one more edge of u leads to a safe node
                if out_deg[u] == 0:
                    queue.append(u)              # all of u's edges lead to safe nodes
        return [u for u in range(n) if safe[u]]  # ascending by construction
